import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';

const Comparison = () => {
  const location = useLocation();
  const { results, videoURL, selectedFeatures, seoData, localVideoPath } = location.state || {};
   console.log('Received states:', { results, videoURL, selectedFeatures, seoData, localVideoPath });
  const [originalSeoData, setOriginalSeoData] = useState(null);
  const [error, setError] = useState(null);

  const fetchOriginalSeo = async () => {
    try {
      const payload = { videoURL };
      const response = await axios.post('http://127.0.0.1:8000/api/fetch-data/', payload, {
        headers: {
          'Content-Type': 'application/json',
        },
      });
      setOriginalSeoData(response.data.data);
      setError(null);
    } catch (err) {
      console.error('Error fetching original SEO data:', err);
      setError('Failed to fetch original SEO data.');
    }
  };

  useEffect(() => {
    if (selectedFeatures.includes('SEO')) {
      fetchOriginalSeo();
    }
  }, [videoURL, selectedFeatures]);

  const calculateImprovement = (original, optimized) => {
    const originalLength = original?.length || 0;
    const optimizedLength = optimized?.length || 0;
    if (originalLength === 0) return '0%';
    const improvement = ((optimizedLength - originalLength) / originalLength * 100).toFixed(1);
    return `${improvement}%`;
  };

  const renderSeoComparison = () => {
    if (!originalSeoData || !seoData) return null;

    return (
      <div className="grid grid-cols-2 gap-6 mb-8">
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Original SEO Metrics</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-medium">Title</h4>
              <p className="text-sm mt-1">{originalSeoData.title || 'No title'}</p>
            </div>
            <div>
              <h4 className="font-medium">Description</h4>
              <p className="text-sm mt-1">{originalSeoData.description || 'No description'}</p>
            </div>
            <div>
              <h4 className="font-medium">Tags</h4>
              <p className="text-sm mt-1">{originalSeoData.tags?.join(', ') || 'No tags'}</p>
            </div>
          </div>
        </div>
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Optimized SEO Metrics</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-medium">Title</h4>
              <p className="text-sm mt-1">{seoData.title || 'No title'}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.title, seoData.title)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Description</h4>
              <p className="text-sm mt-1">{seoData.description || 'No description'}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.description, seoData.description)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Tags</h4>
              <p className="text-sm mt-1">{seoData.tags?.join(', ') || 'No tags'}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.tags?.join(', '), seoData.tags?.join(', '))}
              </p>
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderVideoComparison = () => {
    if (!localVideoPath || !results?.optimized_video_path) return null;

    return (
      <div className="grid grid-cols-2 gap-6 mb-8">
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Original Video</h3>
          <video className="w-full" controls>
            <source src={`http://127.0.0.1:8000${localVideoPath}`} type="video/mp4" />
            Your browser does not support the video tag.
          </video>
        </div>
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Optimized Video</h3>
          <video className="w-full" controls>
            <source src={`http://127.0.0.1:8000${results.optimized_video_path}`} type="video/mp4" />
            Your browser does not support the video tag.
          </video>
        </div>
      </div>
    );
  };

  const renderAudioComparison = () => {
    if (!results?.optimized_audio_path) return null;

    return (
      <div className="grid grid-cols-2 gap-6 mb-8">
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Original Audio</h3>
          <audio className="w-full" controls>
            <source src={`http://127.0.0.1:8000${localVideoPath}`} type="video/mp4" />
            Your browser does not support the audio element.
          </audio>
        </div>
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Optimized Audio</h3>
          <audio className="w-full" controls>
            <source src={`http://127.0.0.1:8000${results.optimized_audio_path}`} type="audio/mpeg" />
            Your browser does not support the audio element.
          </audio>
        </div>
      </div>
    );
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h1 className="text-3xl font-bold mb-8">Video Optimization Comparison</h1>

      {selectedFeatures.includes('SEO') && renderSeoComparison()}
      {selectedFeatures.includes('Video Quality') && renderVideoComparison()}
      {selectedFeatures.includes('Noise Reduction') && renderAudioComparison()}

      {error && <p className="text-red-600 mt-4">{error}</p>}
    </div>
  );
};

export default Comparison;
